(function(){"use strict";const a="http://localhost:5000";async function s(r){const{apiUrl:n=a,ak:e}=await chrome.storage.sync.get(["apiUrl","ak"]);if(!e)throw new Error("Configure your API key in Settings first.");const t=await fetch(`${n.replace(/\/+$/,"")}/api/articles/content`,{method:"POST",headers:{"Content-Type":"application/json","X-Api-Key":e},body:JSON.stringify(r.content)});if(!t.ok)throw new Error(`HTTP ${t.status}: ${await t.text()}`);return{success:!0}}chrome.runtime.onMessage.addListener((r,n,e)=>r.action!=="saveArticle"?!1:(s(r).then(e).catch(t=>{e({success:!1,error:t instanceof Error?t.message:"Failed to save article"})}),!0))})();
